<?php
$pageTitle='Courses'; $basePath=''; require_once __DIR__.'/includes/auth.php'; require_once __DIR__.'/includes/ui.php';
$q=trim($_GET['q']??'');$category=(int)($_GET['category']??0);$sort=$_GET['sort']??'latest';
$categories=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();
$sql="SELECT c.*, u.full_name teacher, cat.name category, (SELECT COUNT(*) FROM enrollments e WHERE e.course_id=c.id) enrollments FROM courses c JOIN users u ON u.id=c.teacher_id LEFT JOIN categories cat ON cat.id=c.category_id WHERE c.status='published'";$params=[];
if($q!==''){$sql.=' AND (c.title LIKE ? OR c.short_description LIKE ? OR c.description LIKE ?)';$like="%$q%";$params=[$like,$like,$like];}
if($category>0){$sql.=' AND c.category_id=?';$params[]=$category;}
$sql.=$sort==='popular'?' ORDER BY enrollments DESC, c.created_at DESC':' ORDER BY c.created_at DESC';
$st=$pdo->prepare($sql);$st->execute($params);$courses=$st->fetchAll();
include __DIR__.'/includes/header.php'; include __DIR__.'/includes/navbar.php'; ?>
<section class="section-sm"><div class="container"><div class="page-header"><div><div class="section-kicker mb-2">Course catalog</div><h1>Explore Courses</h1><p>Find subjects, practice material, and guided learning paths.</p></div><a href="<?=is_logged_in()?e(dashboard_path(user()['role'])):'auth/login.php'?>" class="btn btn-primary"><i class="bi bi-person me-1"></i><?=is_logged_in()?'My Dashboard':'Login'?></a></div>
<form class="card p-3 mb-4" method="get"><div class="row g-3"><div class="col-lg-6"><div class="input-group"><span class="input-group-text bg-white"><i class="bi bi-search"></i></span><input name="q" value="<?=e($q)?>" class="form-control" placeholder="Search courses..."></div></div><div class="col-md-3"><select name="category" class="form-select"><option value="0">All categories</option><?php foreach($categories as $cat): ?><option value="<?=$cat['id']?>" <?=$category===$cat['id']?'selected':''?>><?=e($cat['name'])?></option><?php endforeach; ?></select></div><div class="col-md-3"><select name="sort" class="form-select"><option value="latest" <?=$sort==='latest'?'selected':''?>>Sort: Latest</option><option value="popular" <?=$sort==='popular'?'selected':''?>>Most popular</option></select></div></div><div class="mt-3"><button class="btn btn-primary">Apply filters</button><?php if($q||$category||$sort!=='latest'): ?><a class="btn btn-light ms-2" href="courses.php">Clear</a><?php endif; ?></div></form>
<div class="row g-4"><?php foreach($courses as $i=>$course): ?><div class="col-md-6 col-xl-4"><div class="card course-card card-hover h-100 overflow-hidden"><?=courseThumb($course['category']??'Course',$i)?><div class="card-body d-flex flex-column"><div class="course-meta mb-2"><?=e($course['category']??'General')?> · <?=e($course['level'])?></div><h5 class="card-title"><?=e($course['title'])?></h5><p class="text-muted small"><?=e($course['short_description'])?></p><div class="course-meta d-flex gap-3 mb-3"><span><i class="bi bi-people me-1"></i><?=e($course['enrollments'])?> learners</span><span><i class="bi bi-clock me-1"></i><?=e((string)$course['duration_hours'])?> hrs</span></div><div class="mt-auto d-flex justify-content-between align-items-center"><span class="fw-semibold">Instructor: <?=e($course['teacher'])?></span><a class="btn btn-sm btn-outline-primary" href="course-details.php?id=<?=$course['id']?>">View Course</a></div></div></div></div><?php endforeach; ?></div>
<?php if(!$courses): ?><div class="card empty-state"><div class="icon"><i class="bi bi-search"></i></div><h4>No courses found</h4><p class="text-muted">Try a different keyword or category.</p></div><?php endif; ?></div></section>
<?php include __DIR__.'/includes/footer.php'; ?>
